// Offline tests for the instance's DATABASE_URL gate (infra/aws/templates/check-database-url.sh,
// embedded verbatim in user data). Each case runs the real script with bash and also parses the
// same URL with the node-postgres versions the API runs (resolved through @prisma/adapter-pg, so
// the locked pg and pg-connection-string). The handshake tests then use the actual pg client
// against a local fake PostgreSQL server with throwaway certificates generated by openssl in a
// temporary directory. No AWS, network service or real secret is involved; the passwords below
// are fictional.
//
// Run: pnpm test:infra   (needs bash and openssl on PATH; Git Bash provides both on Windows)

import assert from 'node:assert/strict';
import { Buffer } from 'node:buffer';
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import { createRequire } from 'node:module';
import net from 'node:net';
import os from 'node:os';
import path from 'node:path';
import process from 'node:process';
import tls from 'node:tls';
import { after, before, describe, test } from 'node:test';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const checker = path.resolve(here, '../templates/check-database-url.sh');
const apiRequire = createRequire(path.resolve(here, '../../../apps/api/package.json'));
const adapterRequire = createRequire(apiRequire.resolve('@prisma/adapter-pg'));
const pg = adapterRequire('pg');
const pgRequire = createRequire(adapterRequire.resolve('pg'));
const { parse } = pgRequire('pg-connection-string');
const pgVersion = installedVersion(adapterRequire, 'pg');
const parserVersion = installedVersion(pgRequire, 'pg-connection-string');

function installedVersion(require, name) {
  for (
    let dir = path.dirname(require.resolve(name));
    dir !== path.dirname(dir);
    dir = path.dirname(dir)
  ) {
    const file = path.join(dir, 'package.json');
    if (fs.existsSync(file)) {
      const manifest = JSON.parse(fs.readFileSync(file, 'utf8'));
      if (manifest.name === name) return manifest.version;
    }
  }
  throw new Error(`cannot find the installed version of ${name}`);
}

const RDS_CA = '/etc/tradeflow/rds-ca.pem';
const PASSWORD = 'fictional-0d8f3c';
const HOST = 'tradeflow-portfolio.abc123example.eu-central-1.rds.amazonaws.com';
const BASE = `postgresql://tradeflow_app:${PASSWORD}@${HOST}:5432/tradeflow`;
const VALID = `${BASE}?sslmode=verify-full&sslrootcert=${RDS_CA}`;

function runChecker(input, args = []) {
  const result = spawnSync('bash', [checker, ...args], { input, encoding: 'utf8' });
  if (result.error) throw result.error;
  return result;
}

// Replaces every CA-like (.pem) read during one call with a marker naming the requested path, so the
// effective trust anchor is observable without the instance's /etc/tradeflow.
function withCaFiles(read, fn) {
  const original = fs.readFileSync;
  fs.readFileSync = (file, ...rest) =>
    typeof file === 'string' && file.includes('.pem') ? read(file) : original(file, ...rest);
  try {
    return fn();
  } finally {
    fs.readFileSync = original;
  }
}

const caMarker = (file) => `-----CA ${file}-----`;

// What the API's client would do with the URL: the locked parser's view and the pg client's
// effective TLS options (Prisma's adapter passes the URL as `connectionString` to pg.Pool).
function clientTls(url) {
  return withCaFiles(caMarker, () => {
    const parsed = parse(url);
    const client = new pg.Client({ connectionString: url });
    return { parsed, ssl: client.connectionParameters.ssl, host: client.connectionParameters.host };
  });
}

// Certificate chain and hostname verification both on, anchored to the RDS bundle, for HOST.
function verifiesRdsCertificate({ ssl, host }) {
  return (
    typeof ssl === 'object' &&
    ssl !== null &&
    ssl.rejectUnauthorized !== false &&
    ssl.checkServerIdentity === undefined &&
    ssl.ca === caMarker(RDS_CA) &&
    host === HOST
  );
}

const accepted = [
  ['the documented contract', VALID],
  ['parameters in the other order', `${BASE}?sslrootcert=${RDS_CA}&sslmode=verify-full`],
  [
    'no explicit port',
    `postgresql://tradeflow_app:${PASSWORD}@${HOST}/tradeflow?sslmode=verify-full&sslrootcert=${RDS_CA}`,
  ],
  [
    'a percent-encoded password',
    `postgresql://tradeflow_app:fictional%2Fpw%40x@${HOST}:5432/tradeflow?sslmode=verify-full&sslrootcert=${RDS_CA}`,
  ],
];

// [name, url, what the locked client would do with it if it got through]
//   'weakened': chain or hostname verification off, another CA, or another host
//   'verified': the client would still verify, but the spelling is outside the contract
//   'error': the client would refuse to start
const rejected = [
  ['review case: duplicate sslmode, no-verify last', `${VALID}&sslmode=no-verify`, 'weakened'],
  [
    'duplicate sslmode, no-verify first',
    `${BASE}?sslmode=no-verify&sslmode=verify-full&sslrootcert=${RDS_CA}`,
    'verified',
  ],
  [
    'duplicate sslmode, disable last',
    `${BASE}?sslmode=verify-full&sslrootcert=${RDS_CA}&sslmode=disable`,
    'weakened',
  ],
  [
    'duplicate sslmode, disable first',
    `${BASE}?sslmode=disable&sslrootcert=${RDS_CA}&sslmode=verify-full`,
    'verified',
  ],
  ['sslmode=verify-full twice', `${VALID}&sslmode=verify-full`, 'verified'],
  ['sslmode=no-verify', `${BASE}?sslmode=no-verify&sslrootcert=${RDS_CA}`, 'weakened'],
  ['sslmode=disable', `${BASE}?sslmode=disable&sslrootcert=${RDS_CA}`, 'weakened'],
  ['sslmode=require', `${BASE}?sslmode=require&sslrootcert=${RDS_CA}`, 'verified'],
  ['sslmode=verify-ca', `${BASE}?sslmode=verify-ca&sslrootcert=${RDS_CA}`, 'verified'],
  ['sslmode in upper case', `${BASE}?sslmode=VERIFY-FULL&sslrootcert=${RDS_CA}`, 'verified'],
  ['no sslmode', `${BASE}?sslrootcert=${RDS_CA}`, 'verified'],
  ['no query', BASE, 'weakened'],
  [
    'no sslrootcert (system CAs instead of the RDS bundle)',
    `${BASE}?sslmode=verify-full`,
    'weakened',
  ],
  [
    'CA in another directory',
    `${BASE}?sslmode=verify-full&sslrootcert=/tmp/rds-ca.pem`,
    'weakened',
  ],
  ['CA with a suffix', `${BASE}?sslmode=verify-full&sslrootcert=${RDS_CA}.bak`, 'weakened'],
  [
    'CA path with traversal',
    `${BASE}?sslmode=verify-full&sslrootcert=/etc/tradeflow/../tradeflow/rds-ca.pem`,
    'weakened',
  ],
  ['relative CA path', `${BASE}?sslmode=verify-full&sslrootcert=rds-ca.pem`, 'weakened'],
  ['duplicate sslrootcert, other CA last', `${VALID}&sslrootcert=/tmp/evil.pem`, 'weakened'],
  [
    'duplicate sslrootcert, other CA first',
    `${BASE}?sslrootcert=/tmp/evil.pem&sslmode=verify-full&sslrootcert=${RDS_CA}`,
    'verified',
  ],
  ['sslrootcert twice with the RDS bundle', `${VALID}&sslrootcert=${RDS_CA}`, 'verified'],
  ['encoded name: ssl%6Dode=no-verify', `${VALID}&ssl%6Dode=no-verify`, 'weakened'],
  ['encoded name: %73slmode=disable', `${VALID}&%73slmode=disable`, 'weakened'],
  [
    'encoded name: SSL%6Dode is not sslmode, upper case',
    `${VALID}&SSL%6Dode=no-verify`,
    'verified',
  ],
  [
    'encoded value: sslmode=no%2Dverify',
    `${BASE}?sslmode=no%2Dverify&sslrootcert=${RDS_CA}`,
    'weakened',
  ],
  [
    'encoded value: sslmode=verify%2Dfull',
    `${BASE}?sslmode=verify%2Dfull&sslrootcert=${RDS_CA}`,
    'verified',
  ],
  [
    'encoded value: CA path %2F-encoded',
    `${BASE}?sslmode=verify-full&sslrootcert=%2Fetc%2Ftradeflow%2Frds-ca.pem`,
    'verified',
  ],
  ['encoded value: other CA', `${VALID}&sslrootcert=%2Ftmp%2Fevil.pem`, 'weakened'],
  [
    'encoded separator inside a value',
    `${BASE}?sslmode=verify-full%26sslmode%3Dno-verify&sslrootcert=${RDS_CA}`,
    'verified',
  ],
  ['double-encoded name', `${VALID}&ssl%256Dode=no-verify`, 'verified'],
  ['plus as space', `${BASE}?sslmode=verify+full&sslrootcert=${RDS_CA}`, 'verified'],
  [
    'libpq compatibility turns require into verify-ca',
    `${BASE}?uselibpqcompat=true&sslmode=require&sslrootcert=${RDS_CA}`,
    'weakened',
  ],
  ['host override parameter', `${VALID}&host=db.attacker.example`, 'weakened'],
  ['ssl=0 parameter', `${VALID}&ssl=0`, 'verified'],
  ['client certificate parameter', `${VALID}&sslcert=/tmp/client.pem`, 'verified'],
  ['direct TLS negotiation parameter', `${VALID}&sslnegotiation=direct`, 'verified'],
  ['unknown parameter', `${VALID}&application_name=api`, 'verified'],
  ['upper-case parameter name', `${VALID}&SSLMODE=no-verify`, 'verified'],
  ['fragment hiding a parameter', `${VALID}#&sslmode=no-verify`, 'verified'],
  [
    'semicolon separator',
    `${BASE}?sslmode=verify-full;sslmode=no-verify&sslrootcert=${RDS_CA}`,
    'verified',
  ],
  ['second question mark', `${BASE}?sslmode=verify-full?sslrootcert=${RDS_CA}`, 'weakened'],
  ['empty parameter', `${BASE}?sslmode=verify-full&&sslrootcert=${RDS_CA}`, 'verified'],
  ['trailing ampersand', `${VALID}&`, 'verified'],
  ['leading ampersand', `${BASE}?&sslmode=verify-full&sslrootcert=${RDS_CA}`, 'verified'],
  ['parameter without a value', `${VALID}&sslmode`, 'verified'],
  [
    'newline before a second parameter (the URL parser drops newlines)',
    `${VALID}\n&sslmode=no-verify`,
    'weakened',
  ],
  ['trailing newline', `${VALID}\n`, 'verified'],
  ['carriage return', `${VALID}\r`, 'verified'],
  ['leading space (becomes a relative URL)', ` ${VALID}`, 'weakened'],
  ['embedded space', `${BASE}?sslmode=verify-full &sslrootcert=${RDS_CA}`, 'verified'],
  ['tab', `${VALID}\t`, 'verified'],
  ['non-ASCII hyphen', `${BASE}?sslmode=verify‑full&sslrootcert=${RDS_CA}`, 'verified'],
  ['postgres:// scheme', VALID.replace('postgresql://', 'postgres://'), 'verified'],
  ['upper-case scheme', VALID.replace('postgresql://', 'POSTGRESQL://'), 'verified'],
  [
    'no password',
    `postgresql://tradeflow_app@${HOST}:5432/tradeflow?sslmode=verify-full&sslrootcert=${RDS_CA}`,
    'verified',
  ],
  [
    'no database',
    `postgresql://tradeflow_app:${PASSWORD}@${HOST}:5432/?sslmode=verify-full&sslrootcert=${RDS_CA}`,
    'verified',
  ],
  [
    'raw @ in the password',
    `postgresql://tradeflow_app:a@b@${HOST}/tradeflow?sslmode=verify-full&sslrootcert=${RDS_CA}`,
    'verified',
  ],
  [
    'malformed percent-encoding in the password',
    `postgresql://tradeflow_app:a%zz@${HOST}/tradeflow?sslmode=verify-full&sslrootcert=${RDS_CA}`,
    'verified',
  ],
  ['port 0', VALID.replace(':5432/', ':0/'), 'verified'],
  ['port out of range', VALID.replace(':5432/', ':65536/'), 'error'],
  ['empty input', '', 'weakened'],
];

describe(`check-database-url against pg ${pgVersion} / pg-connection-string ${parserVersion}`, () => {
  test('the locked versions are the ones this contract was written for', () => {
    // A dependency update must re-check the parser semantics these cases encode.
    assert.equal(pgVersion, '8.23.1');
    assert.equal(parserVersion, '2.14.1');
  });

  for (const [name, url] of accepted) {
    test(`accepts ${name}; the client verifies chain and hostname against the RDS bundle`, () => {
      const result = runChecker(url);
      assert.equal(result.status, 0, result.stderr);
      assert.equal(result.stdout + result.stderr, '');
      assert.ok(
        verifiesRdsCertificate(clientTls(url)),
        'pg must keep full verification for an accepted URL',
      );
    });
  }

  for (const [name, url, risk] of rejected) {
    test(`rejects ${name}`, () => {
      const result = runChecker(url);
      assert.equal(result.status, 1, `expected rejection, got status ${String(result.status)}`);
      assert.equal(result.stdout, '');
      assert.match(result.stderr, /^DATABASE_URL rejected: [^\n]+\n$/);
      for (const part of [PASSWORD, HOST, 'no-verify', 'evil', 'attacker']) {
        assert.ok(!result.stderr.includes(part), 'the message must not repeat any part of the URL');
      }

      let observed;
      try {
        observed = verifiesRdsCertificate(clientTls(url)) ? 'verified' : 'weakened';
      } catch {
        observed = 'error';
      }
      assert.equal(
        observed,
        risk,
        'the locked client behaves differently than this case documents',
      );
    });
  }

  test('refuses a URL passed as an argument', () => {
    const result = runChecker(VALID, [VALID]);
    assert.equal(result.status, 1);
    assert.ok(!result.stderr.includes(PASSWORD));
  });

  test('rejects a NUL byte', () => {
    const result = runChecker(`${VALID}\0&sslmode=no-verify`);
    assert.equal(result.status, 1);
  });
});

// --- The actual pg client against a local TLS endpoint ---------------------------------------

const SSL_REQUEST_CODE = 80877103;

// Answers PostgreSQL's SSLRequest with 'S', completes TLS with the given certificate, then fails
// the startup with a recognizable error, so a completed handshake is observable from both sides.
function fakePostgres({ key, cert }) {
  const tlsServer = tls.createServer({ key, cert });
  let handshakes = 0;
  tlsServer.on('secureConnection', (socket) => {
    handshakes += 1;
    socket.once('data', () => {
      const fields = Buffer.from('SFATAL\0C28000\0Mfake server: TLS verified\0\0', 'latin1');
      const header = Buffer.alloc(5);
      header.write('E', 0, 'latin1');
      header.writeInt32BE(fields.length + 4, 1);
      socket.end(Buffer.concat([header, fields]));
    });
  });
  tlsServer.on('tlsClientError', () => {});
  const server = net.createServer((socket) => {
    socket.on('error', () => {});
    socket.once('data', (request) => {
      assert.equal(request.readInt32BE(4), SSL_REQUEST_CODE);
      socket.write('S');
      tlsServer.emit('connection', socket);
    });
  });
  return new Promise((resolve) => {
    server.listen(0, '127.0.0.1', () => {
      resolve({
        port: server.address().port,
        handshakes: () => handshakes,
        close: () => new Promise((done) => server.close(() => done())),
      });
    });
  });
}

async function connectError(url, caPem) {
  const original = fs.readFileSync;
  fs.readFileSync = (file, ...rest) => (file === RDS_CA ? caPem : original(file, ...rest));
  let client;
  try {
    client = new pg.Client({ connectionString: url, connectionTimeoutMillis: 10_000 });
  } finally {
    fs.readFileSync = original;
  }
  client.on('error', () => {});
  try {
    await client.connect();
  } catch (error) {
    return error;
  } finally {
    await client.end().catch(() => {});
  }
  throw new Error('the fake server never accepts a startup');
}

describe('pg client TLS verification with the accepted URL shape', () => {
  let dir;
  const pem = {};

  before(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'tradeflow-db-tls-'));
    const script = `
      set -euo pipefail
      key() { openssl genpkey -algorithm EC -pkeyopt ec_paramgen_curve:P-256 -out "$1" 2> /dev/null; }
      key ca.key
      openssl req -x509 -new -key ca.key -out ca.pem -days 1 -subj "/CN=TradeFlow test CA" \\
        -addext basicConstraints=critical,CA:TRUE -addext keyUsage=critical,keyCertSign
      for name in localhost db.other.test; do
        key "$name.key"
        openssl req -new -key "$name.key" -out "$name.csr" -subj "/CN=$name"
        printf 'subjectAltName=DNS:%s\\nbasicConstraints=CA:FALSE\\nextendedKeyUsage=serverAuth\\n' "$name" > "$name.ext"
        openssl x509 -req -in "$name.csr" -CA ca.pem -CAkey ca.key -CAcreateserial -days 1 \\
          -extfile "$name.ext" -out "$name.pem" 2> /dev/null
      done
      key self.key
      openssl req -x509 -new -key self.key -out self.pem -days 1 -subj "/CN=localhost" \\
        -addext subjectAltName=DNS:localhost
    `;
    const result = spawnSync('bash', ['-c', script], {
      cwd: dir,
      encoding: 'utf8',
      env: { ...process.env, MSYS_NO_PATHCONV: '1', MSYS2_ARG_CONV_EXCL: '*' },
    });
    assert.equal(result.status, 0, `openssl failed: ${result.stderr}`);
    for (const name of ['ca', 'localhost', 'db.other.test', 'self']) {
      pem[name] = fs.readFileSync(path.join(dir, `${name}.pem`), 'utf8');
      if (name !== 'ca')
        pem[`${name}.key`] = fs.readFileSync(path.join(dir, `${name}.key`), 'utf8');
    }
  });

  after(() => {
    if (dir) fs.rmSync(dir, { recursive: true, force: true });
  });

  const urlFor = (port, query = `sslmode=verify-full&sslrootcert=${RDS_CA}`) =>
    `postgresql://tradeflow_app:${PASSWORD}@localhost:${String(port)}/tradeflow?${query}`;

  async function attempt(certName, query) {
    const server = await fakePostgres({ key: pem[`${certName}.key`], cert: pem[certName] });
    try {
      const url = urlFor(server.port, query);
      const error = await connectError(url, pem.ca);
      return { url, error, handshakes: server.handshakes() };
    } finally {
      await server.close();
    }
  }

  test('completes TLS with a certificate for the host from the pinned CA', async () => {
    const { url, error, handshakes } = await attempt('localhost');
    assert.equal(runChecker(url).status, 0);
    assert.equal(handshakes, 1);
    assert.match(error.message, /fake server: TLS verified/);
  });

  test('refuses a certificate from the pinned CA for another hostname', async () => {
    const { url, error, handshakes } = await attempt('db.other.test');
    assert.equal(runChecker(url).status, 0);
    assert.equal(error.code, 'ERR_TLS_CERT_ALTNAME_INVALID');
    assert.equal(handshakes, 0);
  });

  test('refuses a certificate for the host that does not chain to the pinned CA', async () => {
    const { url, error, handshakes } = await attempt('self');
    assert.equal(runChecker(url).status, 0);
    assert.equal(error.code, 'DEPTH_ZERO_SELF_SIGNED_CERT');
    assert.equal(handshakes, 0);
  });

  test('the review case would connect to an untrusted server; the check rejects it', async () => {
    const query = `sslmode=verify-full&sslrootcert=${RDS_CA}&sslmode=no-verify`;
    const { url, error, handshakes } = await attempt('self', query);
    assert.equal(handshakes, 1, 'pg accepts the untrusted certificate with this URL');
    assert.match(error.message, /fake server: TLS verified/);
    assert.equal(runChecker(url).status, 1);
  });
});
